    out = [row[:] for row in grid]
    div = next((r for r,row in enumerate(grid) if row and all(v==2 for v in row)), h)
    sources=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==4]
    for r,c in sources: out[r][c]=0
    for r,c in sources:
        # The color marks a downward diagonal progression, with a repeated
        # chevron fill on the same and following rows, clipped by the divider.
        for k in range(max(0, div-r)):
            rr=r+k
            for cc in (c-k, c+k):
                if 0 <= cc < w and rr < div:
                    out[rr][cc]=4
